--- a/training/level-1/L1-029-retry-policy/nextRetry.mjs
+++ b/training/level-1/L1-029-retry-policy/nextRetry.mjs
@@ -0,0 +1,52 @@
+export function nextRetry({
+  attempt,
+  maxAttempts,
+  baseDelayMs = 1000,
+  maxDelayMs = 30000,
+  multiplier = 2,
+  jitter = 0
+}) {
+  if (typeof attempt !== 'number' || !Number.isFinite(attempt) || attempt < 1) {
+    throw new TypeError('attempt must be a finite integer >= 1');
+  }
+  if (typeof maxAttempts !== 'number' || !Number.isFinite(maxAttempts) || maxAttempts < 1) {
+    throw new TypeError('maxAttempts must be a finite integer >= 1');
+  }
+  if (typeof baseDelayMs !== 'number' || !Number.isFinite(baseDelayMs) || baseDelayMs < 0) {
+    throw new TypeError('baseDelayMs must be a finite number >= 0');
+  }
+  if (typeof maxDelayMs !== 'number' || !Number.isFinite(maxDelayMs) || maxDelayMs < 0) {
+    throw new TypeError('maxDelayMs must be a finite number >= 0');
+  }
+  if (typeof multiplier !== 'number' || !Number.isFinite(multiplier) || multiplier < 1) {
+    throw new TypeError('multiplier must be a finite number >= 1');
+  }
+  if (typeof jitter !== 'number' || !Number.isFinite(jitter) || jitter < 0 || jitter > 1) {
+    throw new TypeError('jitter must be a finite number in [0, 1]');
+  }
+
+  if (attempt >= maxAttempts) {
+    return Object.freeze({
+      retry: false,
+      nextAttempt: null,
+      delayMs: null,
+      reason: 'MAX_ATTEMPTS'
+    });
+  }
+
+  const exponentialDelay = baseDelayMs * Math.pow(multiplier, attempt - 1);
+  let delayMs = Math.min(maxDelayMs, exponentialDelay);
+  
+  if (jitter > 0) {
+    delayMs = delayMs * (1 + jitter);
+  }
+  
+  delayMs = Math.round(delayMs);
+
+  return Object.freeze({
+    retry: true,
+    nextAttempt: attempt + 1,
+    delayMs,
+    reason: 'RETRY'
+  });
+}

